export const SUBS: { from: number; to: number; text: string }[] = [{"from": 36, "to": 96, "text": "अगर आप एक YouTube Creator हो,"}, {"from": 97, "to": 232, "text": "तो आप जानते हो कि एक अच्छी वीडियो बनाने में कितनी मेहनत लगती है।"}, {"from": 245, "to": 375, "text": "सबसे पहले एक अच्छा topic ढूँढना पड़ता है। फिर research करनी होती है,"}, {"from": 376, "to": 489, "text": "script लिखनी होती है, title और thumbnail तैयार करना होता है,"}, {"from": 490, "to": 627, "text": "और वीडियो publish करने के बाद उसकी performance भी analyze करनी पड़ती है।"}, {"from": 641, "to": 795, "text": "लेकिन सोचिए, अगर आपके पास एक ऐसा AI assistant हो जो आपके चैनल को समझता हो,"}, {"from": 796, "to": 850, "text": "आपकी audience को जानता हो,"}, {"from": 851, "to": 1001, "text": "और आपकी content creation journey के अलग-अलग हिस्सों में आपकी मदद कर सके?"}, {"from": 1015, "to": 1121, "text": "यहीं पर Claude AI आपके लिए काफी useful हो सकता है।"}, {"from": 1135, "to": 1283, "text": "आज हम सीखेंगे कि Claude को एक personal YouTube content assistant की तरह कैसे"}, {"from": 1284, "to": 1311, "text": "setup करना है।"}, {"from": 1324, "to": 1452, "text": "हम Projects, custom instructions, reference files, Skills, video ideas,"}, {"from": 1453, "to": 1573, "text": "thumbnail concepts और analytics workflows को step by step समझेंगे।"}, {"from": 1586, "to": 1698, "text": "और सबसे अच्छी बात, हम केवल theory नहीं देखेंगे।"}, {"from": 1699, "to": 1825, "text": "हर important feature का practical example भी समझेंगे।"}, {"from": 1859, "to": 1944, "text": "सबसे पहले समझते हैं कि Claude AI क्या है।"}, {"from": 1957, "to": 2121, "text": "Claude एक AI assistant है, जिसे Anthropic ने develop किया है।"}, {"from": 2135, "to": 2260, "text": "इसकी मदद से आप लिख सकते हो, जानकारी को समझ सकते हो,"}, {"from": 2261, "to": 2443, "text": "documents analyze कर सकते हो और अपने creative कामों में सहायता ले सकते हो।"}, {"from": 2456, "to": 2592, "text": "एक YouTube Creator के लिए Claude का सबसे बड़ा फायदा सिर्फ script लिखना नहीं"}, {"from": 2593, "to": 2597, "text": "है।"}, {"from": 2611, "to": 2766, "text": "असली फायदा तब मिलता है जब आप इसे अपने चैनल से जुड़ा सही context देते हो।"}, {"from": 2779, "to": 2865, "text": "मान लीजिए आप technology videos बनाते हो।"}, {"from": 2866, "to": 3010, "text": "आपका बोलने का style Hindi-Hinglish है, आपकी audience beginners हैं,"}, {"from": 3011, "to": 3119, "text": "और आप आसान examples के साथ topics explain करते हो।"}, {"from": 3132, "to": 3199, "text": "अगर Claude को ये सारी बातें मालूम हों,"}, {"from": 3200, "to": 3299, "text": "तो वह आपके लिए ज्यादा relevant content तैयार कर सकता है।"}, {"from": 3313, "to": 3433, "text": "इसीलिए हमें सबसे पहले AI को अपने चैनल के बारे में सिखाना होगा।"}, {"from": 3467, "to": 3566, "text": "अब मान लीजिए आपको एक नई वीडियो की script लिखवानी है।"}, {"from": 3580, "to": 3695, "text": "Normally आपको AI को बताना पड़ता है कि आपके चैनल का niche क्या है,"}, {"from": 3696, "to": 3803, "text": "audience कैसी है, language क्या है, वीडियो कितनी लंबी चाहिए,"}, {"from": 3804, "to": 3871, "text": "और आपका writing style कैसा होना चाहिए।"}, {"from": 3884, "to": 3956, "text": "अगर आप बार-बार अलग-अलग काम करते हो,"}, {"from": 3957, "to": 4084, "text": "तो यह सारी instructions repeat करना time-consuming हो सकता है।"}, {"from": 4098, "to": 4238, "text": "इसी problem को आसान बनाने के लिए Claude में Projects का इस्तेमाल किया जा सकता"}, {"from": 4239, "to": 4323, "text": "है, जहाँ यह feature आपके account पर उपलब्ध हो।"}, {"from": 4336, "to": 4474, "text": "Project एक dedicated workspace होता है जिसमें आप किसी खास काम के लिए relevant"}, {"from": 4475, "to": 4575, "text": "instructions और reference materials organize कर सकते हो।"}, {"from": 4589, "to": 4710, "text": "एक YouTube Creator अपने चैनल के लिए अलग Project बना सकता है।"}, {"from": 4724, "to": 4875, "text": "उसके बाद उसी workspace में नई chats शुरू करके channel-related tasks कर सकता"}, {"from": 4876, "to": 4881, "text": "है।"}, {"from": 4894, "to": 5046, "text": "इस तरह आप बार-बार शुरुआत से पूरी जानकारी लिखने की जरूरत कम कर सकते हो।"}, {"from": 5059, "to": 5167, "text": "लेकिन याद रखिए, AI का output हमेशा review करना जरूरी है,"}, {"from": 5168, "to": 5281, "text": "क्योंकि saved context होने के बाद भी AI गलतियाँ कर सकता है।"}, {"from": 5315, "to": 5369, "text": "अब practical setup समझते हैं।"}, {"from": 5383, "to": 5505, "text": "सबसे पहले Claude के Projects section में जाइए और नया Project create कीजिए।"}, {"from": 5519, "to": 5635, "text": "हम इस example में Project का नाम रखेंगे YouTube Content Assistant।"}, {"from": 5649, "to": 5811, "text": "इसके बाद आपको अपने Project का purpose clearly define करना है।"}, {"from": 5825, "to": 5867, "text": "जैसे, Help me research,"}, {"from": 5868, "to": 5982, "text": "plan and create high-quality YouTube content for my audience."}, {"from": 5996, "to": 6076, "text": "अब सबसे important हिस्सा है Project Instructions."}, {"from": 6089, "to": 6224, "text": "यहाँ आप Claude को बताएँगे कि वह आपके लिए किस role में काम करेगा।"}, {"from": 6237, "to": 6375, "text": "उदाहरण के लिए, तुम मेरे YouTube content strategy assistant हो।"}, {"from": 6376, "to": 6505, "text": "तुम्हारा काम है मुझे engaging scripts, better video ideas,"}, {"from": 6506, "to": 6637, "text": "compelling titles और thumbnail concepts बनाने में मदद करना।"}, {"from": 6650, "to": 6730, "text": "इसके साथ आपको अपने चैनल का niche, audience,"}, {"from": 6731, "to": 6819, "text": "language और writing style भी specify करना चाहिए।"}, {"from": 6833, "to": 6920, "text": "आप जितना clear और useful context दोगे,"}, {"from": 6921, "to": 7027, "text": "Claude के लिए आपके goals समझना उतना आसान होगा।"}, {"from": 7061, "to": 7162, "text": "Project Instructions में केवल चैनल का नाम लिखना काफी नहीं है।"}, {"from": 7176, "to": 7288, "text": "आपको अपनी content identity भी explain करनी चाहिए।"}, {"from": 7302, "to": 7399, "text": "सबसे पहले बताइए कि आपका ideal viewer कौन है।"}, {"from": 7413, "to": 7574, "text": "उसे किस तरह की problems face करनी पड़ती हैं? वह आपके वीडियो क्यों देखता है?"}, {"from": 7575, "to": 7669, "text": "और वीडियो देखने के बाद उसे क्या सीखना चाहिए?"}, {"from": 7683, "to": 7756, "text": "इसके बाद अपनी brand voice define कीजिए।"}, {"from": 7770, "to": 7892, "text": "आप educational content बनाते हो, entertaining videos बनाते हो,"}, {"from": 7893, "to": 7975, "text": "या documentary-style storytelling करते हो?"}, {"from": 7989, "to": 8089, "text": "आपकी भाषा formal होनी चाहिए या conversational?"}, {"from": 8090, "to": 8209, "text": "आप छोटे sentences पसंद करते हो या detailed explanation?"}, {"from": 8222, "to": 8340, "text": "इसके बाद अपने content creation workflow के बारे में बताइए।"}, {"from": 8354, "to": 8495, "text": "आपको research में मदद चाहिए, scriptwriting में, title generation में,"}, {"from": 8496, "to": 8548, "text": "या analytics analysis में?"}, {"from": 8562, "to": 8718, "text": "यह सारी information Claude को आपके लिए ज्यादा useful creative partner बनने में"}, {"from": 8719, "to": 8749, "text": "मदद कर सकती है।"}, {"from": 8783, "to": 8918, "text": "अब आता है एक बहुत useful step, reference files add करना।"}, {"from": 8931, "to": 9052, "text": "मान लीजिए आपने पिछले कुछ महीनों में कई YouTube videos upload की हैं।"}, {"from": 9066, "to": 9219, "text": "आप अपने अच्छे perform करने वाले videos की scripts को reference के तौर पर"}, {"from": 9220, "to": 9378, "text": "Project में add कर सकते हो, अगर आपके account में file upload available है।"}, {"from": 9391, "to": 9447, "text": "इससे Claude आपके writing patterns,"}, {"from": 9448, "to": 9556, "text": "explanations और content structure को better understand कर सकता है।"}, {"from": 9570, "to": 9701, "text": "इसके अलावा आप YouTube Studio से analytics data भी export कर सकते हो।"}, {"from": 9715, "to": 9791, "text": "YouTube Studio खोलिए, Analytics में जाइए,"}, {"from": 9792, "to": 9915, "text": "और जरूरत के अनुसार Advanced Mode में अपनी date range select कीजिए।"}, {"from": 9929, "to": 10092, "text": "फिर उपलब्ध export option का इस्तेमाल करके CSV data download कीजिए।"}, {"from": 10105, "to": 10201, "text": "इस data में video titles, views, impressions,"}, {"from": 10202, "to": 10304, "text": "click-through rate और दूसरे metrics हो सकते हैं।"}, {"from": 10317, "to": 10406, "text": "लेकिन केवल वही data share कीजिए जो जरूरी हो।"}, {"from": 10407, "to": 10548, "text": "Sensitive information और private details को पहले remove करना बेहतर है।"}, {"from": 10562, "to": 10629, "text": "अब आपके पास channel instructions,"}, {"from": 10630, "to": 10729, "text": "sample scripts और analytics data तीनों तैयार हैं।"}, {"from": 10763, "to": 10880, "text": "अब देखते हैं कि यह setup practical काम कैसे कर सकता है।"}, {"from": 10894, "to": 11006, "text": "अपने YouTube Project के अंदर नई chat शुरू कीजिए।"}, {"from": 11019, "to": 11060, "text": "और Claude से पूछिए,"}, {"from": 11061, "to": 11223, "text": "मेरे चैनल की audience और पिछले वीडियो topics के आधार पर पाँच नए video ideas"}, {"from": 11224, "to": 11249, "text": "suggest करो।"}, {"from": 11262, "to": 11403, "text": "Claude उपलब्ध project context और reference material को इस्तेमाल करके ideas"}, {"from": 11404, "to": 11435, "text": "तैयार कर सकता है।"}, {"from": 11449, "to": 11510, "text": "लेकिन यहाँ एक जरूरी बात है।"}, {"from": 11524, "to": 11669, "text": "AI से मिले ideas automatically trending या guaranteed successful नहीं होते।"}, {"from": 11683, "to": 11732, "text": "आपको उन्हें audience demand,"}, {"from": 11733, "to": 11856, "text": "search interest और अपने channel goals के आधार पर evaluate करना चाहिए।"}, {"from": 11870, "to": 11940, "text": "अब किसी एक topic को select करके बोलिए,"}, {"from": 11941, "to": 12076, "text": "इस idea के लिए एक engaging introduction और detailed script outline बनाओ।"}, {"from": 12089, "to": 12164, "text": "आप चाहो तो उसे examples add करने,"}, {"from": 12165, "to": 12326, "text": "भाषा आसान करने और वीडियो को ज्यादा engaging बनाने के लिए भी कह सकते हो।"}, {"from": 12340, "to": 12465, "text": "इस तरह Claude आपके research और planning process में एक useful assistant बन"}, {"from": 12466, "to": 12479, "text": "सकता है।"}, {"from": 12513, "to": 12624, "text": "अब बात करते हैं Claude के एक और interesting concept की, Skills."}, {"from": 12638, "to": 12770, "text": "Skills ऐसे reusable instructions और resources हो सकते हैं जो किसी particular"}, {"from": 12771, "to": 12858, "text": "task को repeatable तरीके से करने में मदद करते हैं।"}, {"from": 12872, "to": 12980, "text": "मान लीजिए आपको हर हफ्ते YouTube titles generate करने होते हैं।"}, {"from": 12994, "to": 13145, "text": "हर बार एक लंबा prompt लिखने के बजाय आप एक structured workflow तैयार कर सकते"}, {"from": 13146, "to": 13151, "text": "हो।"}, {"from": 13165, "to": 13292, "text": "यह workflow समझा सकता है कि अच्छे title में clarity, curiosity,"}, {"from": 13293, "to": 13398, "text": "accuracy और audience relevance कैसे balance करनी है।"}, {"from": 13412, "to": 13483, "text": "इसी तरह आप script review, intro writing,"}, {"from": 13484, "to": 13619, "text": "thumbnail brainstorming और channel analysis के लिए भी reusable instructions"}, {"from": 13620, "to": 13641, "text": "बना सकते हो।"}, {"from": 13654, "to": 13766, "text": "Skills का इस्तेमाल और उनकी availability आपके Claude product,"}, {"from": 13767, "to": 13843, "text": "plan और environment पर depend कर सकती है।"}, {"from": 13857, "to": 13977, "text": "हम इस tutorial में इनके practical concepts को समझेंगे और दिखाएँगे कि एक"}, {"from": 13978, "to": 14076, "text": "creator इन्हें अपने workflow में कैसे organize कर सकता है।"}, {"from": 14110, "to": 14293, "text": "मान लीजिए आपको जानना है कि आपके चैनल पर कौन से videos अच्छा perform कर रहे हैं"}, {"from": 14294, "to": 14392, "text": "और किन videos को improve करने की जरूरत है।"}, {"from": 14405, "to": 14539, "text": "इसके लिए आप YouTube Analytics CSV को analyze करवा सकते हो।"}, {"from": 14553, "to": 14689, "text": "एक structured reporting workflow Claude को बता सकता है कि views, impressions,"}, {"from": 14690, "to": 14805, "text": "CTR, watch time और subscriber performance कैसे summarize करनी है।"}, {"from": 14818, "to": 14841, "text": "उदाहरण के लिए,"}, {"from": 14842, "to": 14964, "text": "अगर किसी वीडियो को impressions मिल रहे हैं लेकिन click-through rate कम है,"}, {"from": 14965, "to": 15064, "text": "तो उसके title और thumbnail को review करना उपयोगी हो सकता है।"}, {"from": 15078, "to": 15235, "text": "लेकिन सिर्फ CTR देखकर पूरी performance का फैसला नहीं करना चाहिए। Topic,"}, {"from": 15236, "to": 15361, "text": "traffic source, audience और video age भी महत्वपूर्ण हैं।"}, {"from": 15374, "to": 15476, "text": "इसी तरह आप देख सकते हो कि किन videos से subscribers आए,"}, {"from": 15477, "to": 15566, "text": "किन topics पर viewers ने ज्यादा interest दिखाया,"}, {"from": 15567, "to": 15643, "text": "और कहाँ improvement के opportunities हैं।"}, {"from": 15657, "to": 15786, "text": "इस पूरी information से एक readable report card तैयार किया जा सकता है।"}, {"from": 15799, "to": 15877, "text": "अच्छी analytics केवल numbers नहीं बताती,"}, {"from": 15878, "to": 15963, "text": "बल्कि better decisions लेने में मदद करती है।"}, {"from": 15997, "to": 16088, "text": "अब एक practical example देखते हैं, Title Writer."}, {"from": 16102, "to": 16239, "text": "एक अच्छा YouTube title viewer को यह समझाने में मदद करता है कि वीडियो उसके लिए"}, {"from": 16240, "to": 16272, "text": "क्यों relevant है।"}, {"from": 16285, "to": 16429, "text": "हम Claude को instruction दे सकते हैं कि किसी भी topic के लिए पाँच या छह"}, {"from": 16430, "to": 16505, "text": "different title options generate करो।"}, {"from": 16518, "to": 16589, "text": "हर title clear हो, interesting हो,"}, {"from": 16590, "to": 16707, "text": "और वीडियो के actual content को accurately represent करे।"}, {"from": 16721, "to": 16824, "text": "साथ ही Claude से पूछ सकते हैं कि किस title में curiosity है,"}, {"from": 16825, "to": 16959, "text": "किसमें specific benefit है, और किसमें search-friendly wording इस्तेमाल हुई है।"}, {"from": 16973, "to": 17104, "text": "फिर हम इन titles को compare करके सबसे suitable option select कर सकते हैं।"}, {"from": 17118, "to": 17221, "text": "आप Claude से यह भी कह सकते हो कि title को थोड़ा छोटा करो,"}, {"from": 17222, "to": 17342, "text": "language ज्यादा natural बनाओ, या unnecessary clickbait remove करो।"}, {"from": 17355, "to": 17491, "text": "Repeated testing और feedback से आपका workflow ज्यादा consistent हो सकता है।"}, {"from": 17504, "to": 17533, "text": "लेकिन याद रखिए,"}, {"from": 17534, "to": 17679, "text": "AI-generated scores या predictions actual YouTube performance की guarantee"}, {"from": 17680, "to": 17697, "text": "नहीं हैं।"}, {"from": 17731, "to": 17878, "text": "अब बात करते हैं दो बहुत important content creation elements की,"}, {"from": 17879, "to": 17939, "text": "intro hooks और thumbnails."}, {"from": 17953, "to": 18099, "text": "YouTube पर शुरुआत के कुछ seconds viewer को यह समझाने के लिए महत्वपूर्ण होते"}, {"from": 18100, "to": 18169, "text": "हैं कि वीडियो आगे क्यों देखनी चाहिए।"}, {"from": 18183, "to": 18322, "text": "Claude की मदद से आप एक ही topic के लिए different opening hooks brainstorm कर"}, {"from": 18323, "to": 18336, "text": "सकते हो।"}, {"from": 18350, "to": 18451, "text": "जैसे एक question-based hook, एक surprising observation,"}, {"from": 18452, "to": 18574, "text": "एक problem-solution opening, या एक direct educational introduction."}, {"from": 18588, "to": 18734, "text": "फिर आप अपने चैनल की style और audience के हिसाब से सबसे natural hook choose कर"}, {"from": 18735, "to": 18750, "text": "सकते हो।"}, {"from": 18763, "to": 18835, "text": "इसके बाद आता है Thumbnail Ideation."}, {"from": 18849, "to": 18990, "text": "यहाँ आप Claude को अपना topic दे सकते हो और उससे multiple thumbnail concepts"}, {"from": 18991, "to": 19031, "text": "generate करवा सकते हो।"}, {"from": 19045, "to": 19161, "text": "हर concept के साथ आप visual composition, background colors,"}, {"from": 19162, "to": 19285, "text": "main subject और short thumbnail text के suggestions ले सकते हो।"}, {"from": 19299, "to": 19386, "text": "लेकिन final thumbnail बनाते समय readability,"}, {"from": 19387, "to": 19486, "text": "accuracy और visual clarity का ध्यान रखना जरूरी है।"}, {"from": 19499, "to": 19561, "text": "AI से ideas लेना useful है,"}, {"from": 19562, "to": 19689, "text": "लेकिन final creative judgment creator का ही होना चाहिए।"}, {"from": 19723, "to": 19827, "text": "अब इन सारे features को एक साथ जोड़कर देखते हैं।"}, {"from": 19840, "to": 19964, "text": "सबसे पहले आप अपने channel के लिए dedicated Project setup करते हो।"}, {"from": 19977, "to": 20069, "text": "फिर उसमें audience information, brand voice,"}, {"from": 20070, "to": 20195, "text": "writing preferences और relevant reference files add करते हो।"}, {"from": 20208, "to": 20337, "text": "इसके बाद Claude से नए video topics brainstorm करवा सकते हो।"}, {"from": 20351, "to": 20441, "text": "Selected topic के लिए research outline,"}, {"from": 20442, "to": 20580, "text": "engaging introduction और script structure तैयार कर सकते हो।"}, {"from": 20593, "to": 20713, "text": "Title Writer workflow से multiple titles compare कर सकते हो।"}, {"from": 20727, "to": 20868, "text": "Thumbnail Ideation से visual concepts explore कर सकते हो।"}, {"from": 20882, "to": 21019, "text": "और वीडियो publish होने के बाद analytics data की मदद से समझ सकते हो कि क्या"}, {"from": 21020, "to": 21112, "text": "अच्छा perform हुआ और क्या improve किया जा सकता है।"}, {"from": 21125, "to": 21224, "text": "इस तरह आपका workflow एक organized system बन जाता है।"}, {"from": 21237, "to": 21369, "text": "Claude आपकी creativity को replace नहीं करता। वह planning, drafting,"}, {"from": 21370, "to": 21509, "text": "analysis और repetitive tasks को manage करने में आपकी सहायता कर सकता है।"}, {"from": 21543, "to": 21707, "text": "तो अब आप समझ गए होंगे कि Claude AI को सिर्फ एक normal chatbot की तरह इस्तेमाल"}, {"from": 21708, "to": 21851, "text": "करने के बजाय एक structured content assistant कैसे बनाया जा सकता है।"}, {"from": 21865, "to": 22006, "text": "Projects से आप relevant context organize कर सकते हो।"}, {"from": 22019, "to": 22171, "text": "Skills और reusable instructions से अपने repeated tasks को streamline कर सकते"}, {"from": 22172, "to": 22177, "text": "हो।"}, {"from": 22190, "to": 22351, "text": "और analytics के साथ AI की मदद लेकर अपने content decisions को ज्यादा informed"}, {"from": 22352, "to": 22377, "text": "बना सकते हो।"}, {"from": 22391, "to": 22531, "text": "सबसे important बात, हमेशा अपने content को review करो, facts verify करो,"}, {"from": 22532, "to": 22604, "text": "और अपनी original creativity बनाए रखो।"}, {"from": 22618, "to": 22680, "text": "अगर आपको यह tutorial useful लगा,"}, {"from": 22681, "to": 22830, "text": "तो वीडियो को like कीजिए और ऐसे ही AI tools और YouTube creation tutorials के"}, {"from": 22831, "to": 22885, "text": "लिए चैनल को subscribe कीजिए।"}, {"from": 22899, "to": 22955, "text": "मिलते हैं अगली वीडियो में!"}];
